'use strict';
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict'),{chromium}=require('playwright');
const root=path.resolve(__dirname,'..'),out=process.env.JY_LIUREN_REVIEW||path.join(require('node:os').tmpdir(),'jingyue-liuren-review');fs.mkdirSync(out,{recursive:true});
const types={'.html':'text/html','.js':'text/javascript','.mjs':'text/javascript','.css':'text/css','.svg':'image/svg+xml','.webp':'image/webp','.png':'image/png','.jpg':'image/jpeg','.jpeg':'image/jpeg','.json':'application/json','.woff2':'font/woff2','.mp3':'audio/mpeg'};
async function routes(page,missing){await page.route('**/*',async route=>{const u=new URL(route.request().url());if(u.origin!=='https://jingyue.uk')return route.abort();if(u.pathname.startsWith('/api/'))return route.fulfill({contentType:'application/json',body:'{"ok":true,"count":1,"live":1,"total":1}'});const file=path.resolve(root,'.'+decodeURIComponent(u.pathname==='/'?'/index.html':u.pathname));if(!file.startsWith(root+path.sep))return route.abort();try{return await route.fulfill({body:fs.readFileSync(file),contentType:types[path.extname(file)]||'application/octet-stream'});}catch(e){missing.push(u.pathname);return route.fulfill({status:404,body:''});}});}
async function layout(page){return page.locator('#lr-room').evaluate(room=>({overflow:room.scrollWidth>innerWidth+1,bad:[...room.querySelectorAll('button,input,textarea,select')].filter(e=>e.getClientRects().length).map(e=>({id:e.id||e.textContent.trim().slice(0,24),r:e.getBoundingClientRect()})).filter(x=>x.r.left<-1||x.r.right>innerWidth+1).map(x=>x.id),footerVisible:room.querySelector('.lr-footer').getBoundingClientRect().bottom<=innerHeight+1}));}
async function download(page,action,ext){const event=page.waitForEvent('download');await page.locator('[data-lr-action='+action+']').click();const d=await event;assert.equal(d.suggestedFilename(),'jingyue-liuren-2026-10-01.'+ext);return fs.readFileSync(await d.path(),ext==='png'?undefined:'utf8');}
(async()=>{
 const launch=()=>chromium.launch({executablePath:process.env.JY_CHROMIUM||chromium.executablePath(),args:['--no-sandbox','--disable-dev-shm-usage','--enable-unsafe-swiftshader'].concat(process.env.JY_SINGLE_PROCESS?['--no-zygote','--single-process','--in-process-gpu','--disable-crash-reporter']:[])}),report=[];let browser;
 try{
  for(const width of(process.env.JY_LIUREN_WIDTHS?process.env.JY_LIUREN_WIDTHS.split(',').map(Number):[320,390,768,1440])){
   browser=await launch();const context=await browser.newContext({viewport:{width,height:width<800?844:960},serviceWorkers:'block',reducedMotion:'reduce',acceptDownloads:true}),page=await context.newPage(),errors=[],missing=[];
   page.on('pageerror',e=>errors.push(e.message));await routes(page,missing);await page.addInitScript(()=>{window.__lrCopied='';Object.defineProperty(navigator,'clipboard',{value:{writeText:async value=>{window.__lrCopied=value;}}});});await page.goto('https://jingyue.uk',{waitUntil:'load'});await page.locator('.at-liuren-card').waitFor();
   const banner=await page.locator('.at-liuren-card').boundingBox(),grid=await page.locator('.at-tools').boundingBox(),name=await page.locator('.at-name-card').boundingBox();assert(Math.abs(banner.width-name.width)<2,'matching paired widths');assert(Math.abs(banner.y-name.y)<2,'name and liuren share a row');assert(banner.x>name.x+name.width,'liuren is the right card');assert(Math.abs(banner.x+banner.width-(grid.x+grid.width))<2,'complete final row');assert.equal(await page.locator('.at-tools [data-tool]').count(),14);
   await page.locator('.at-liuren-card').scrollIntoViewIfNeeded();await page.screenshot({path:path.join(out,'liuren-home-'+width+'.png')});await page.locator('.at-liuren-card').click();await page.locator('#lr-question').fill('這次合作能否落實？目前卡在哪裡，我可以先做什麼？');await page.locator('#lr-date').fill('2026-10-01');await page.locator('#lr-time').fill('22:06');
   const form=await layout(page);assert.equal(form.overflow,false);assert.deepEqual(form.bad,[]);assert.equal(form.footerVisible,true);await page.locator('#lr-main').evaluate(e=>{e.scrollTop=0;});await page.screenshot({path:path.join(out,'liuren-form-'+width+'.png')});await page.locator('#lr-cast').click();await page.locator('.lr-transmission').first().waitFor();
   let data=await page.evaluate(()=>JYLiurenRoom.getState().result);assert.equal(data.monthGeneral.branch,'辰');assert.deepEqual(data.transmissions.map(t=>t.branch),['卯','申','丑']);assert.equal(await page.locator('.lr-svg-palace').count(),12);assert.equal(await page.locator('.lr-course').count(),4);assert.equal(await page.locator('#lr-room').getAttribute('data-phase'),'4');const native=JSON.stringify(data);
   const result=await layout(page);assert.equal(result.overflow,false);assert.deepEqual(result.bad,[]);assert.equal(result.footerVisible,true);await page.screenshot({path:path.join(out,'liuren-round-'+width+'.png')});
   await page.locator('[data-lr-course="2"]').scrollIntoViewIfNeeded();await page.locator('[data-lr-course="2"]').click();let state=await page.evaluate(()=>JYLiurenRoom.getState());assert.equal(state.focusKind,'course');assert.equal(state.selected,data.courses[2].lowerBranch);assert.equal(await page.locator('[data-lr-course="2"]').getAttribute('aria-pressed'),'true');assert((await page.locator('#lr-inspect').innerText()).includes('第3課'));
   await page.locator('[data-lr-transmission="1"]').click();state=await page.evaluate(()=>JYLiurenRoom.getState());assert.equal(state.selected,data.transmissions[1].earthIndex);
   await page.locator('#lr-angle').fill('90');await page.locator('#lr-angle').dispatchEvent('input');assert.equal(await page.evaluate(()=>JYLiurenRoom.getState().angle),90);assert.equal(JSON.stringify(await page.evaluate(()=>JYLiurenRoom.getState().result)),native);await page.locator('[data-lr-action=tilt]').click();assert.equal(await page.locator('#lr-plate').evaluate(e=>e.classList.contains('is-tilted')),true);await page.locator('[data-lr-action=reset-view]').click();assert.equal(await page.evaluate(()=>JYLiurenRoom.getState().angle),0);
   await page.locator('[data-lr-view=square]').click();assert.equal(await page.locator('.lr-square-palace').count(),12);assert.equal(await page.locator('.lr-square-center').count(),1);await page.locator('[data-lr-palace="5"]').click();assert.equal(await page.evaluate(()=>JYLiurenRoom.getState().selected),5);assert.deepEqual((await layout(page)).bad,[]);await page.locator('#lr-main').evaluate(e=>{e.scrollTop=0;});await page.screenshot({path:path.join(out,'liuren-square-'+width+'.png')});
   await page.locator('#lr-tab-trace').click();assert((await page.locator('.lr-policy').innerText()).includes('秋分'));assert((await page.locator('.lr-trace-list').innerText()).includes('元首'));await page.locator('#lr-tab-trace').focus();await page.keyboard.press('ArrowRight');assert.equal(await page.locator('#lr-tab-guide').getAttribute('aria-selected'),'true');await page.locator('#lr-notes').fill('我已提供方案；尚未收到正式回覆。');await page.locator('[data-lr-action=copy]').click();const text=await page.evaluate(()=>window.__lrCopied);assert(text.includes(data.question));assert(text.includes('尚未收到正式回覆'));assert(text.includes('九宗門'));assert(text.includes('本次資料與記憶邊界'));assert.equal((text.match(/願你諸事順遂。/g)||[]).length,1);
   if(width===390){
    const saved=JSON.parse(await download(page,'download','json'));assert.equal(saved.schema,'jy.liuren-export/1');assert.deepEqual(saved.facts,data);assert(saved.prompt.includes(saved.notes));const png=await download(page,'image','png');assert.equal(png.subarray(0,8).toString('hex'),'89504e470d0a1a0a');fs.writeFileSync(path.join(out,'liuren-export.png'),png);const svg=await download(page,'image-svg','svg');assert(svg.startsWith('<svg'));assert(svg.includes('卯'));fs.writeFileSync(path.join(out,'liuren-export.svg'),svg);assert.equal(await page.evaluate(s=>new DOMParser().parseFromString(s,'image/svg+xml').querySelector('parsererror')!==null,svg),false);
    await page.locator('#lr-tab-chart').click();await page.locator('[data-lr-view=round]').click();await page.locator('.lr-instrument-canvas').waitFor();await page.locator('.lr-instrument-canvas').focus();await page.keyboard.press('ArrowUp');assert.equal(await page.evaluate(()=>JYLiurenRoom.getState().selected),6);
    await page.emulateMedia({reducedMotion:'no-preference'});await page.locator('[data-lr-action=replay]').click();assert.equal(await page.locator('#lr-room').getAttribute('data-phase'),'0');await page.locator('[data-lr-action=skip]').click();assert.equal(await page.locator('#lr-room').getAttribute('data-phase'),'4');assert.equal(JSON.stringify(await page.evaluate(()=>JYLiurenRoom.getState().result)),native);
    await page.locator('[data-lr-action=replay]').click();await page.waitForFunction(()=>document.querySelector('#lr-room').dataset.phase==='4');await page.locator('[data-lr-action=replay]').click();await page.keyboard.press('Escape');assert.equal(await page.locator('#lr-room').count(),0);await page.locator('.at-liuren-card').click();assert.equal(await page.locator('#lr-room').getAttribute('data-phase'),'4');assert.equal(await page.evaluate(()=>JYLiurenRoom.getState().notes),'我已提供方案；尚未收到正式回覆。');
    await page.locator('[data-lr-action=edit]').click();await page.locator('#lr-question').fill('</textarea><img id="lr-injected" src=x>');await page.locator('[data-lr-action=now]').click();assert.equal(await page.locator('#lr-injected').count(),0);assert.equal(await page.locator('#lr-question').inputValue(),'</textarea><img id="lr-injected" src=x>');await page.locator('#lr-date').fill('2026-10-01');await page.locator('#lr-time').fill('22:06');await page.locator('#lr-input-form details summary').click();await page.locator('#lr-hour').selectOption('午');await page.locator('#lr-month').selectOption('午');await page.locator('#lr-noble').selectOption('night');await page.locator('#lr-cast').click();await page.locator('.lr-transmission').first().waitFor();assert.equal(await page.evaluate(()=>JYLiurenRoom.getState().result.method.gate),'伏吟');assert.equal(await page.locator('#lr-injected').count(),0);assert.equal(await page.evaluate(()=>JYLiurenRoom.getState().notes),'');
   }
   await page.keyboard.press('Escape');assert.equal(await page.locator('#lr-room').count(),0);assert.equal(await page.evaluate(()=>document.activeElement.getAttribute('data-tool')),'liuren');assert.notEqual(await page.evaluate(()=>document.body.style.overflow),'hidden');assert.equal(await page.locator('.at-liuren-card').evaluate(e=>e.closest('[inert]')),null);assert.deepEqual(errors,[],'page errors '+width);assert.deepEqual(missing,[],'missing assets '+width);report.push({width,form,result,errors,missing});await context.close();await browser.close();browser=null;console.log('PASS '+width+'px: native chart, round/square, linked courses, exports, notes and modal lifecycle');
  }
  fs.writeFileSync(path.join(out,'report.json'),JSON.stringify(report,null,2));
 }finally{if(browser)await browser.close();}
})().catch(e=>{console.error(e.stack);process.exitCode=1;});
